mapper.select:


    and rule_name like concat('%', #{ruleName}, '%')
    and document_type = #{documentType}
    and transfer_type = #{transferType}
    and scope_type = #{scopeType}
    and condition_type = #{conditionType}
    and approval_mode = #{approvalMode}
    and status = #{status}
    and create_time >= #{params.beginCreateTime}
    and create_time <= #{params.endCreateTime}

order by priority asc, rule_id asc

where status = '0' and document_type = 'transfer' and ( transfer_type = 'all'
or transfer_type = #{transferType}
) and ( scope_type = 'all'
or (scope_type in ('from_dept', 'dept') and scope_id = #{fromDeptId}) or (scope_type in ('region', 'area') and exists ( select 1 from sys_dept from_dept where from_dept.dept_id = #{fromDeptId} and ( from_dept.dept_id = inv_transfer_approval_rule.scope_id or find_in_set(inv_transfer_approval_rule.scope_id, from_dept.ancestors) ) ))
or (scope_type in ('to_dept', 'dept') and scope_id = #{toDeptId}) or (scope_type in ('region', 'area') and exists ( select 1 from sys_dept to_dept where to_dept.dept_id = #{toDeptId} and ( to_dept.dept_id = inv_transfer_approval_rule.scope_id or find_in_set(inv_transfer_approval_rule.scope_id, to_dept.ancestors) ) ))
) order by priority asc, rule_id asc

mapper.delete:
delete from inv_transfer_approval_rule
where rule_id = #{ruleId}
  and version = #{expectedVersion}
